        { id: "d6q2", pergunta: "Por que Nínive não foi destruída naquele momento?", opcoes: ["Porque Jonas se recusou a entregar a mensagem", "Porque o povo creu e mudou de rumo", "Porque Deus decidiu esperar a próxima geração", "Porque o rei da Assíria fez aliança com Israel"], correta: 1, explicacao: "Os ninivitas deram crédito à mensagem e mudaram de rumo (Jonas 3:10). Gerações posteriores voltaram à maldade, e então o juízo veio." },
        { id: "d6q3", pergunta: "Verdadeiro ou falso: segundo a lição, a missão do profeta se resume a prever o futuro.", opcoes: ["Verdadeiro", "Falso"], correta: 1, explicacao: "Falso. Prever o futuro é apenas parte da missão: os profetas chamam o povo de volta à Palavra e oferecem orientação, advertência e encorajamento." },
        { id: "d6q4", pergunta: "Uma profecia condicional anuncia juízo, mas o povo se arrepende. Segundo Jeremias 18:7-10, o que pode acontecer?", opcoes: ["O profeta passa a ser considerado falso", "Deus pode revogar o mal anunciado", "O juízo vem de qualquer forma no prazo", "A profecia é transferida para outro povo"], correta: 1, explicacao: "Deus pode revogar o mal anunciado se houver arrependimento — ou retirar o bem prometido se houver rebeldia. Isso não torna o profeta falso." }
